import { galleryForms } from '@/data/community';

export function Gallery() {
  return (
    <section id="formas-de-hacer-click" className="gallery-section section-rail" aria-labelledby="gallery-heading">
      <div className="section-label">
        <span>03 / FORMAS DE HACER CLICK</span>
        <span>NO SON PROYECTOS TERMINADOS. SON CAMINOS PARA EMPEZAR.</span>
      </div>
      <div className="section-heading-row">
        <h2 id="gallery-heading">Hay muchas formas<br/><em>de hacer click.</em></h2>
        <p>Cada colaboración empieza con algo concreto: un conocimiento, una herramienta, una conexión. Estas son seis maneras de sumar a un proyecto.</p>
      </div>
      <ul className="gallery-grid">
        {galleryForms.map(form => (
          <li key={form.number} className="gallery-card">
            <div className="gallery-media">
              <span className="gallery-index">{form.number}</span>
              <img
                src={form.image}
                srcSet={form.srcSet}
                sizes="(min-width: 1000px) 30vw, (min-width: 620px) 45vw, 100vw"
                alt={form.alt}
                width={1216}
                height={912}
                loading="lazy"
                decoding="async"
              />
            </div>
            <div className="gallery-copy">
              <h3>{form.title}</h3>
              <p>{form.description}</p>
            </div>
          </li>
        ))}
      </ul>
      <p className="gallery-note">Esta galería presenta formas de colaborar, no proyectos realizados. Cuando existan proyectos reales aprobados, podrán incorporarse aquí como fichas dinámicas.</p>
    </section>
  );
}

